mapper.update:
UPDATE article_info
SET status=#{status},update_time=NOW()
WHERE article_id=#{articleId}

mapper.select:
SELECT CAST(user_id AS CHAR) AS userId,nick_name AS nickName,role
FROM user_info
WHERE user_id=#{userId}

SELECT CAST(a.article_id AS CHAR) AS articleId,a.title,u.nick_name AS authorName,a.status,a.required_level AS requiredLevel,a.view_count AS viewCount,a.update_time AS updateTime
FROM article_info a
LEFT
JOIN user_info u ON u.user_id=a.user_id
WHERE a.deleted=0 AND a.status IN(1,2) AND (a.title LIKE #{pattern} ESCAPE '!' OR u.nick_name LIKE #{pattern} ESCAPE '!')
 AND a.status=#{status}

ORDER BY a.update_time DESC,a.article_id DESC
LIMIT #{size}
OFFSET #{offset}
